.stickysim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #20242e;
    background: linear-gradient(160deg, #f5f1ea 0%, #eae3d6 100%);
    border-radius: 18px;
}

.stickysim-container * {
    box-sizing: border-box;
}

.stickysim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #14233f 0%, #233a63 55%, #2f4d7a 100%);
    color: #f7f3ea;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(20, 35, 63, 0.32);
}

.stickysim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #f7f3ea;
}

.stickysim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e3c887;
    background: rgba(227, 200, 135, 0.14);
    padding: 5px 14px;
    border-radius: 999px;
}

.stickysim-subtitle {
    margin: 10px auto 0;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e6ddcd;
}

.stickysim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2b3a55;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.stickysim-period-counter #currentDay,
.stickysim-period-counter #maxPeriods {
    font-weight: 800;
    color: #14233f;
}

.stickysim-round-name {
    background: #dfe6f0;
    color: #14233f;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.stickysim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a5b12;
    background: #f6e7cd;
    padding: 4px 12px;
    border-radius: 999px;
}

.stickysim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.stickysim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e3dccd;
    box-shadow: 0 4px 14px rgba(20, 35, 63, 0.07);
    border-top: 4px solid #2f4d7a;
}

.stickysim-card-behavior { border-top-color: #1f7a4d; }
.stickysim-card-transfer { border-top-color: #2f4d7a; }
.stickysim-card-credibility { border-top-color: #8a5cc0; }
.stickysim-card-budget { border-top-color: #c08a16; }

.stickysim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6c7385;
}

.stickysim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #14233f;
}

.stickysim-card-behavior .stickysim-value { color: #1f7a4d; }
.stickysim-card-transfer .stickysim-value { color: #2f4d7a; }
.stickysim-card-credibility .stickysim-value { color: #8a5cc0; }
.stickysim-card-budget .stickysim-value { color: #c08a16; }

.stickysim-sublabel {
    font-size: 0.75rem;
    color: #818799;
    line-height: 1.35;
}

.stickysim-behavior-fail .stickysim-value { color: #c0392b; }
.stickysim-behavior-target .stickysim-value { color: #1f7a4d; }

.stickysim-budget-over { border-top-color: #c0392b; }
.stickysim-budget-over .stickysim-value { color: #c0392b; }

.stickysim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #14233f;
    color: #f1ecdf;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.stickysim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e3c887;
}

.stickysim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c08a16;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(20, 35, 63, 0.06);
}

.stickysim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.stickysim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #14233f;
    margin-bottom: 6px;
}

.stickysim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #353b49;
}

.stickysim-briefing-text strong { color: #1f7a4d; }
.stickysim-briefing-text em { color: #9a5b12; font-style: italic; }

.stickysim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e3dccd;
    box-shadow: 0 4px 14px rgba(20, 35, 63, 0.07);
}

.stickysim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #14233f;
    border-bottom: 2px solid #eee6d6;
    padding-bottom: 8px;
}

.stickysim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #24314c;
    margin: 14px 0 6px;
}

.stickysim-container select,
.stickysim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cdc2ab;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbf8f2;
    color: #20242e;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.stickysim-container select:focus,
.stickysim-container input[type="number"]:focus {
    outline: none;
    border-color: #2f4d7a;
    box-shadow: 0 0 0 3px rgba(47, 77, 122, 0.16);
}

.stickysim-container select option {
    background-color: #ffffff;
    color: #20242e;
}

.stickysim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c08a16;
}

.stickysim-range-readout,
.stickysim-spend-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #233a63;
    margin-top: 4px;
}

.stickysim-range-readout span:last-child,
.stickysim-spend-readout span:nth-child(2) {
    color: #1f7a4d;
    font-weight: 800;
}

.stickysim-hint {
    font-size: 0.8rem;
    color: #818799;
    margin-top: 4px;
    line-height: 1.4;
}

.stickysim-addon-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.stickysim-addon-row {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    background: #faf6ee;
    border: 1px solid #e7ddc9;
    border-radius: 9px;
    padding: 10px 12px;
    margin: 0;
    cursor: pointer;
    font-weight: 600;
}

.stickysim-addon-row input[type="checkbox"] {
    margin-top: 3px;
    width: 18px;
    height: 18px;
    flex: 0 0 18px;
    accent-color: #1f7a4d;
}

.stickysim-addon-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #24314c;
    line-height: 1.4;
}

.stickysim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.stickysim-container .btn-primary {
    background: linear-gradient(135deg, #1f7a4d 0%, #2f4d7a 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #ffffff;
    box-shadow: 0 6px 16px rgba(31, 122, 77, 0.28);
}

.stickysim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.stickysim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cdc2ab;
    color: #6c7385;
}

.stickysim-coach {
    background: #14233f;
    color: #eef0f5;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(20, 35, 63, 0.24);
}

.stickysim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e3c887;
    margin-bottom: 8px;
}

.stickysim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.stickysim-coach-body strong { color: #f0cf8a; }
.stickysim-coach-body em { color: #f3c6a8; font-style: italic; }

.stickysim-history,
.stickysim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e3dccd;
    box-shadow: 0 4px 14px rgba(20, 35, 63, 0.07);
}

.stickysim-history h3,
.stickysim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #14233f;
}

.stickysim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #24314c;
}

.stickysim-container table#usfHistoryTable th {
    background: #f1ece1;
    color: #14233f;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e0d6c2;
}

.stickysim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ebdf;
}

.stickysim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf7f0;
}

.stickysim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .stickysim-container {
        padding: 14px;
    }
    .stickysim-header h1 {
        font-size: 1.7rem;
    }
    .stickysim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .stickysim-value {
        font-size: 2rem;
    }
    .stickysim-clock {
        margin-left: 0;
    }
    .stickysim-period-counter {
        font-size: 0.88rem;
    }
    .stickysim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .stickysim-addon-row {
        flex-wrap: nowrap;
    }
    .stickysim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion modal (append-only, dark-on-light) ===== */
.stickysim-completion { color:#232636; font-size:0.95rem; }
.stickysim-cm-head { text-align:center; margin-bottom:16px; }
.stickysim-cm-score { font-size:3.2rem; font-weight:800; line-height:1; color:#4a5aa8; }
.stickysim-cm-score-max { font-size:1.2rem; font-weight:600; color:#8892c4; }
.stickysim-cm-grade { font-size:1.2rem; font-weight:700; margin-top:6px; color:#161b30; }
.stickysim-cm-badge { display:inline-block; margin-left:6px; padding:2px 10px; border-radius:999px; font-size:0.78rem; font-weight:700; vertical-align:middle; }
.stickysim-cm-yes { background:rgba(74,90,168,0.14); color:#3c4a9a; border:1px solid rgba(74,90,168,0.5); }
.stickysim-cm-no { background:rgba(201,138,22,0.16); color:#8a6a1f; border:1px solid rgba(201,138,22,0.5); }
.stickysim-cm-fail { background:rgba(192,57,43,0.12); color:#b0392b; border:1px solid rgba(192,57,43,0.45); }
.stickysim-cm-metrics { display:flex; flex-wrap:wrap; gap:10px; justify-content:center; margin:12px 0 16px; }
.stickysim-cm-metric { flex:1 1 110px; min-width:100px; background:rgba(22,27,48,0.06); border:1px solid rgba(22,27,48,0.16); border-radius:10px; padding:10px 8px; text-align:center; }
.stickysim-cm-mv { display:block; font-size:1.4rem; font-weight:800; color:#1f2540; }
.stickysim-cm-ml { display:block; font-size:0.72rem; margin-top:4px; color:#6c7385; text-transform:uppercase; letter-spacing:0.03em; }
.stickysim-cm-insights-title { font-weight:700; margin:8px 0 6px; color:#161b30; }
.stickysim-cm-insights { margin:0; padding-left:20px; }
.stickysim-cm-insights li { margin:4px 0; color:#2c3350; }

