(function() {
    'use strict';

    class StickyAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Learning that Sticks`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (USD, in $k).
            this.BUDGET_CAP = 480;        // $480,000 all-in
            this.TARGET_BEHAVIOR = 60;    // renewal-grade leading indicator at day 90
            this.MEAS_LOW = 60;           // recommended measurement spend floor ($60k)
            this.MEAS_HIGH = 80;          // recommended measurement spend ceiling ($80k)

            // Format costs ($k).
            this.FORMAT_COST = { blended: 210, action: 240, manager: 130, intensive: 165, selfpaced: 95 };
            // Add-on costs ($k).
            this.ADDON_COST = { project: 55, reinforce: 25, coach: 60, peer: 40 };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    behavior: 12,
                    transfer: 10,
                    credibility: 15,
                    budgetUsed: 0,
                    reserveSet: 0,
                    measureSpent: 0,
                    overBudget: false,
                    overclaimed: false,
                    behaviorHistory: [12],
                    transferHistory: [10],
                    credibilityHistory: [15],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            // Seed a deliberately MIDDLING default mix — a click-through must not auto-win.
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    challenge: `leadership`,
                    focus: 50,
                    indicator: `system`,
                    format: `intensive`,
                    addProject: false,
                    addReinforce: false,
                    addCoach: false,
                    addPeer: false,
                    reserve: 20,
                    levels: `learning`,
                    isolation: `estimation`,
                    measureSpend: 30,
                    restraint: 50,
                    interpret: `positive`,
                    roi: `modest`,
                    recommendation: `redesign`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ch = document.getElementById(`challengeInput`);
                const fo = document.getElementById(`focusInput`);
                const ind = document.getElementById(`indicatorInput`);
                if (ch) decisions.challenge = ch.value;
                if (fo) decisions.focus = parseInt(fo.value, 10);
                if (ind) decisions.indicator = ind.value;
                if (!Number.isFinite(decisions.focus) || decisions.focus < 0 || decisions.focus > 100) {
                    warn(`warn_focus_range`); return false;
                }
            } else if (round === 2) {
                const fmt = document.getElementById(`formatInput`);
                if (fmt) decisions.format = fmt.value;
                const pr = document.getElementById(`addProjectInput`);
                const re = document.getElementById(`addReinforceInput`);
                const co = document.getElementById(`addCoachInput`);
                const pe = document.getElementById(`addPeerInput`);
                if (pr) decisions.addProject = pr.checked;
                if (re) decisions.addReinforce = re.checked;
                if (co) decisions.addCoach = co.checked;
                if (pe) decisions.addPeer = pe.checked;
                const rsv = document.getElementById(`reserveInput`);
                if (rsv) decisions.reserve = parseFloat(rsv.value);
                if (!Number.isFinite(decisions.reserve) || decisions.reserve < 0) {
                    warn(`warn_reserve_negative`); return false;
                }
                // Delivery + reserve must fit the $480k cap.
                const fmtCost = this.FORMAT_COST[decisions.format] || 0;
                let addonCost = 0;
                if (decisions.addProject) addonCost += this.ADDON_COST.project;
                if (decisions.addReinforce) addonCost += this.ADDON_COST.reinforce;
                if (decisions.addCoach) addonCost += this.ADDON_COST.coach;
                if (decisions.addPeer) addonCost += this.ADDON_COST.peer;
                if (fmtCost + addonCost + decisions.reserve > this.BUDGET_CAP) {
                    warn(`warn_over_cap`); return false;
                }
            } else if (round === 3) {
                const lv = document.getElementById(`levelsInput`);
                const iso = document.getElementById(`isolationInput`);
                const ms = document.getElementById(`measureSpendInput`);
                const rt = document.getElementById(`restraintInput`);
                if (lv) decisions.levels = lv.value;
                if (iso) decisions.isolation = iso.value;
                if (ms) decisions.measureSpend = parseFloat(ms.value);
                if (rt) decisions.restraint = parseInt(rt.value, 10);
                if (!Number.isFinite(decisions.measureSpend) || decisions.measureSpend < 0) {
                    warn(`warn_measure_negative`); return false;
                }
                if (!Number.isFinite(decisions.restraint) || decisions.restraint < 0 || decisions.restraint > 100) {
                    warn(`warn_restraint_range`); return false;
                }
                // Measurement spend must fit inside the remaining budget.
                const remaining = this.BUDGET_CAP - window.mySimulation.state.domainState.budgetUsed;
                if (decisions.measureSpend > remaining) {
                    warn(`warn_measure_overbudget`); return false;
                }
            } else if (round === 4) {
                const it = document.getElementById(`interpretInput`);
                const ro = document.getElementById(`roiInput`);
                const rc = document.getElementById(`recommendationInput`);
                const cv = document.getElementById(`convictionInput`);
                if (it) decisions.interpret = it.value;
                if (ro) decisions.roi = ro.value;
                if (rc) decisions.recommendation = rc.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // behaviorDelta = the day-90 leading indicator (the renewal metric);
            // transferDelta = how well learning moves into the daily flow of work;
            // credibilityDelta = how defensible the measurement / claims are to the CFO.
            let behaviorDelta = 0, transferDelta = 0, credibilityDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: choose ONE challenge. All-three dilutes depth below the measurable
                // threshold (Common Error 1).
                if (d.challenge === `all`) {
                    behaviorDelta -= 10; transferDelta -= 6; credibilityDelta -= 6; coachKey = `coach_r1_all`;
                } else {
                    behaviorDelta += 12; transferDelta += 4; coachKey = `coach_r1_focus`;
                }

                // Focus discipline — concentrating depth on one measurable behavior.
                if (d.challenge !== `all` && d.focus >= 65) { behaviorDelta += 8; transferDelta += 3; }
                else if (d.focus <= 30) { behaviorDelta -= 6; coachKey = `coach_r1_diffuse`; }

                // Leading indicator: an observed behavior index or a system-data signal proves
                // behavior change; satisfaction/completion does not; "later" starves measurement.
                switch (d.indicator) {
                    case `observed`: behaviorDelta += 8; credibilityDelta += 12; break;
                    case `system`: behaviorDelta += 6; credibilityDelta += 8; break;
                    case `satisfaction`: credibilityDelta -= 8; coachKey = `coach_r1_satisfaction`; break;
                    case `none`: behaviorDelta -= 4; credibilityDelta -= 10; coachKey = `coach_r1_nomeasure`; break;
                }

                const sharp = d.challenge !== `all` && d.focus >= 65 && (d.indicator === `observed` || d.indicator === `system`);
                if (sharp) coachKey = `coach_r1_sharp`;
                summaryKey = sharp ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Design for transfer-of-learning (70-20-10), not appeal. Buy a single event and
                // the forgetting curve erases it (Common Error 3).
                const fmtCost = this.FORMAT_COST[d.format] || 0;
                spend += fmtCost;
                switch (d.format) {
                    case `action`: transferDelta += 16; behaviorDelta += 8; coachKey = `coach_r2_action`; break;
                    case `blended`: transferDelta += 13; behaviorDelta += 7; coachKey = `coach_r2_blended`; break;
                    case `manager`: transferDelta += 11; behaviorDelta += 6; coachKey = `coach_r2_manager`; break;
                    case `intensive`: transferDelta -= 6; behaviorDelta += 1; coachKey = `coach_r2_intensive`; break;
                    case `selfpaced`: transferDelta -= 4; behaviorDelta += 1; coachKey = `coach_r2_selfpaced`; break;
                }

                // AI-adoption challenge is a change problem, not a content problem (Common Error 5):
                // self-paced tutorials alone fail; manager-cascade / coaching is the adoption lever.
                if (d.challenge === `ai`) {
                    if (d.format === `selfpaced` || d.format === `intensive`) {
                        behaviorDelta -= 8; transferDelta -= 6; coachKey = `coach_r2_aitools`;
                    } else if (d.format === `manager` || d.addCoach) {
                        behaviorDelta += 6; transferDelta += 4; coachKey = `coach_r2_aiadopt`;
                    }
                }

                // Reinforcement add-ons move learning into the flow of work.
                let addonCount = 0;
                if (d.addProject) { spend += this.ADDON_COST.project; transferDelta += 6; behaviorDelta += 4; credibilityDelta += 5; addonCount++; }
                if (d.addReinforce) { spend += this.ADDON_COST.reinforce; transferDelta += 8; behaviorDelta += 5; addonCount++; }
                if (d.addCoach) { spend += this.ADDON_COST.coach; transferDelta += 6; behaviorDelta += 4; addonCount++; }
                if (d.addPeer) { spend += this.ADDON_COST.peer; transferDelta += 4; behaviorDelta += 2; addonCount++; }

                // The forgetting curve: a one-shot format with no reinforcement reverts.
                if ((d.format === `intensive` || d.format === `selfpaced`) && addonCount === 0) {
                    transferDelta -= 6; behaviorDelta -= 4; coachKey = `coach_r2_event`;
                }

                // Reserve for measurement — Catalyst's whole promise is the impact report
                // (Common Error 2). Reserve is parked, not spent yet (spent in Round 3).
                ds.reserveSet = d.reserve;
                if (d.reserve >= this.MEAS_LOW) { credibilityDelta += 10; }
                else if (d.reserve >= 40) { credibilityDelta += 4; }
                else if (d.reserve < 25) { credibilityDelta -= 8; coachKey = `coach_r2_starve`; }

                const designGood = (d.format === `action` || d.format === `blended` || d.format === `manager`) && addonCount >= 1 && d.reserve >= this.MEAS_LOW;
                if (designGood) coachKey = `coach_r2_strong`;
                summaryKey = designGood ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Commit the measurement plan. Fund Behavior (L3) and Results (L4), where the
                // promise lives — L1-L2 are cheap but don't honor the promise (Common Error 2).
                switch (d.levels) {
                    case `behavior_results`: behaviorDelta += 8; credibilityDelta += 16; coachKey = `coach_r3_levels`; break;
                    case `learning`: credibilityDelta -= 4; coachKey = `coach_r3_l2`; break;
                    case `reaction`: behaviorDelta -= 2; credibilityDelta -= 12; coachKey = `coach_r3_l1`; break;
                }

                // Phillips ROI isolation. A comparison group beats expert estimation; claiming the
                // whole gain with no isolation destroys credibility (Common Error 4).
                switch (d.isolation) {
                    case `comparison`: credibilityDelta += 12; behaviorDelta += 3; break;
                    case `estimation`: credibilityDelta += 4; break;
                    case `claimall`: credibilityDelta -= 14; ds.overclaimed = true; coachKey = `coach_r3_claimall`; break;
                }

                // Measurement spend funds the 90-day behavior + results capture.
                spend += d.measureSpend;
                const totalMeasure = ds.reserveSet >= d.measureSpend ? d.measureSpend : d.measureSpend;
                ds.measureSpent = d.measureSpend;
                if (d.measureSpend >= this.MEAS_LOW && d.measureSpend <= this.MEAS_HIGH) {
                    behaviorDelta += 10; credibilityDelta += 10;
                } else if (d.measureSpend > this.MEAS_HIGH) {
                    // Over-investing in measurement starves delivery — diminishing returns.
                    behaviorDelta += 6; credibilityDelta += 8; transferDelta -= 3; coachKey = `coach_r3_overmeasure`;
                } else if (d.measureSpend >= 40) {
                    behaviorDelta += 4; credibilityDelta += 4;
                } else {
                    behaviorDelta -= 4; credibilityDelta -= 8; coachKey = `coach_r3_thin`;
                }

                // Restraint: stating what the data does NOT claim builds credibility.
                if (d.restraint >= 60) { credibilityDelta += 6; }
                else if (d.restraint <= 25) { credibilityDelta -= 6; coachKey = `coach_r3_norestraint`; }

                const planGood = d.levels === `behavior_results` && d.isolation !== `claimall` && d.measureSpend >= this.MEAS_LOW;
                if (planGood && d.isolation === `comparison`) coachKey = `coach_r3_strong`;
                summaryKey = planGood ? `sum_r3_good` : (d.isolation === `claimall` ? `sum_r3_overclaim` : `sum_r3_weak`);
            } else if (round === 4) {
                // Defend impact & win the renewal. Honest interpretation separates cause from
                // correlation; spin destroys credibility (Common Error 4).
                switch (d.interpret) {
                    case `honest`: credibilityDelta += 14; behaviorDelta += 4; coachKey = `coach_r4_honest`; break;
                    case `positive`: credibilityDelta += 2; coachKey = `coach_r4_positive`; break;
                    case `spin`: credibilityDelta -= 14; behaviorDelta -= 2; ds.overclaimed = true; coachKey = `coach_r4_spin`; break;
                }

                // The ROI you put in front of the CFO. A defensible, isolated number beats an
                // impressive one you can't prove (Common Error 4).
                switch (d.roi) {
                    case `isolated`: credibilityDelta += 14; behaviorDelta += 4; break;
                    case `modest`: credibilityDelta += 8; break;
                    case `inflated`: credibilityDelta -= 16; ds.overclaimed = true; coachKey = `coach_r4_inflated`; break;
                }

                // Renewal recommendation — commercial discipline, not craft for its own sake.
                switch (d.recommendation) {
                    case `renew`: behaviorDelta += 6; transferDelta += 4; credibilityDelta += 4; break;
                    case `redesign`: behaviorDelta += 2; credibilityDelta += 6; coachKey = `coach_r4_redesign`; break;
                    case `declare`: credibilityDelta -= 10; coachKey = `coach_r4_declare`; break;
                }

                // Conviction nudges credibility around the neutral 50 point.
                credibilityDelta += Math.round((d.conviction - 50) / 8);

                const wins = d.interpret === `honest` && (d.roi === `isolated` || d.roi === `modest`) && d.recommendation === `renew`;
                if (wins) coachKey = `coach_r4_win`;
                summaryKey = wins ? `sum_r4_good` : (ds.overclaimed ? `sum_r4_overclaim` : `sum_r4_weak`);
            }

            // Resource accounting (in $k, capped at $480k; mark overspend).
            const newBudget = ds.budgetUsed + spend;
            if (newBudget > this.BUDGET_CAP) ds.overBudget = true;
            ds.budgetUsed = Math.min(this.BUDGET_CAP, Math.round(newBudget));

            // KPIs move on their deltas, bounded 0–100.
            ds.behavior = Math.max(0, Math.min(100, ds.behavior + behaviorDelta));
            ds.transfer = Math.max(0, Math.min(100, ds.transfer + transferDelta));
            ds.credibility = Math.max(0, Math.min(100, ds.credibility + credibilityDelta));

            ds.behaviorHistory.push(Math.round(ds.behavior));
            ds.transferHistory.push(Math.round(ds.transfer));
            ds.credibilityHistory.push(Math.round(ds.credibility));
            ds.performance = { overallScore: this._composite(ds) };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                behavior: Math.round(ds.behavior),
                behaviorDelta: Math.round(behaviorDelta),
                transfer: Math.round(ds.transfer),
                transferDelta: Math.round(transferDelta),
                credibility: Math.round(ds.credibility),
                credibilityDelta: Math.round(credibilityDelta),
                budgetUsed: ds.budgetUsed,
                overBudget: ds.overBudget,
                overclaimed: ds.overclaimed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`behaviorDisplay`, `domainState.behavior`, (v) => {
                const card = document.querySelector(`.stickysim-card-behavior`);
                if (card) {
                    card.classList.toggle(`stickysim-behavior-target`, Number(v) >= this.TARGET_BEHAVIOR);
                    card.classList.toggle(`stickysim-behavior-fail`, Number(v) < this.TARGET_BEHAVIOR);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`transferDisplay`, `domainState.transfer`, (v) => Math.round(v));
            uiManager.bind(`credibilityDisplay`, `domainState.credibility`, (v) => Math.round(v));
            uiManager.bind(`budgetCardDisplay`, `domainState.budgetUsed`, (v) => {
                const card = document.querySelector(`.stickysim-card-budget`);
                if (card) card.classList.toggle(`stickysim-budget-over`, !!this.state && false);
                return `$` + Math.round(Number(v)) + `k`;
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const card = document.querySelector(`.stickysim-card-budget`);
                const ds = window.mySimulation.state.domainState;
                if (card) card.classList.toggle(`stickysim-budget-over`, !!(ds && ds.overBudget));
                return `$` + Math.round(Number(v)) + `k / $480k`;
            });

            // Focus slider readout.
            const fo = document.getElementById(`focusInput`);
            const foReadout = document.getElementById(`focusReadout`);
            if (fo && foReadout) {
                foReadout.textContent = fo.value;
                fo.addEventListener(`input`, function() { foReadout.textContent = fo.value; });
            }

            // Restraint slider readout.
            const rt = document.getElementById(`restraintInput`);
            const rtReadout = document.getElementById(`restraintReadout`);
            if (rt && rtReadout) {
                rtReadout.textContent = rt.value;
                rt.addEventListener(`input`, function() { rtReadout.textContent = rt.value; });
            }

            // Live committed-spend readout for Round 2 (format + add-ons + reserve).
            const self = this;
            const spendReadout = document.getElementById(`spendReadout`);
            const recompute = function() {
                const fmtEl = document.getElementById(`formatInput`);
                let total = fmtEl ? (self.FORMAT_COST[fmtEl.value] || 0) : 0;
                if (document.getElementById(`addProjectInput`) && document.getElementById(`addProjectInput`).checked) total += self.ADDON_COST.project;
                if (document.getElementById(`addReinforceInput`) && document.getElementById(`addReinforceInput`).checked) total += self.ADDON_COST.reinforce;
                if (document.getElementById(`addCoachInput`) && document.getElementById(`addCoachInput`).checked) total += self.ADDON_COST.coach;
                if (document.getElementById(`addPeerInput`) && document.getElementById(`addPeerInput`).checked) total += self.ADDON_COST.peer;
                const rsvEl = document.getElementById(`reserveInput`);
                if (rsvEl) total += (parseFloat(rsvEl.value) || 0);
                if (spendReadout) spendReadout.textContent = `$` + Math.round(total) + `k`;
                if (spendReadout) spendReadout.style.color = (total > self.BUDGET_CAP) ? `#c0392b` : ``;
            };
            [`formatInput`, `addProjectInput`, `addReinforceInput`, `addCoachInput`, `addPeerInput`, `reserveInput`].forEach((id) => {
                const el = document.getElementById(id);
                if (el) {
                    el.addEventListener(`change`, recompute);
                    el.addEventListener(`input`, recompute);
                }
            });
            recompute();
        }

        _composite(ds) {
            const behavior = Math.round(ds.behavior);
            const transfer = Math.round(ds.transfer);
            const credibility = Math.round(ds.credibility);
            return Math.round(behavior * 0.40 + transfer * 0.25 + credibility * 0.35);
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

