        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.behaviorHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                stickyChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.behaviorHistory },
                        { data: ds.transferHistory },
                        { data: ds.credibilityHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const behavior = Math.round(ds.behavior);
            const transfer = Math.round(ds.transfer);
            const credibility = Math.round(ds.credibility);

            const hitTarget = behavior >= this.TARGET_BEHAVIOR;
            const defensible = credibility >= 60;
            const sticks = transfer >= 50;
            const overclaimed = ds.overclaimed || (hitTarget && credibility < 40);
            const composite = this._composite(ds);

            let performanceKey = `grade_lost`;
            if (hitTarget && defensible && sticks && composite >= 70) performanceKey = `grade_won`;
            else if (hitTarget && defensible) performanceKey = `grade_credible`;
            else if (overclaimed) performanceKey = `grade_overclaim`;
            else if (hitTarget) performanceKey = `grade_thin`;
            else if (behavior > 35) performanceKey = `grade_short`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (hitTarget && defensible && sticks) insights.push(window.mySimulation.t(`insight_won`));
            else if (overclaimed) insights.push(window.mySimulation.t(`insight_overclaim`));
            else if (hitTarget) insights.push(window.mySimulation.t(`insight_thin`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (transfer < 45) insights.push(window.mySimulation.t(`insight_forgetting`));
            if (credibility < 45) insights.push(window.mySimulation.t(`insight_credibility`));
            if (ds.overBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (hitTarget && defensible && sticks && credibility >= 70) insights.push(window.mySimulation.t(`insight_pipeline`));

            return {
                behavior: behavior,
                transfer: transfer,
                credibility: credibility,
                hitTarget: hitTarget,
                overclaimed: overclaimed,
                composite: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                sound: (hitTarget && defensible && sticks),
                overclaimedFlag: overclaimed,
                overBudget: ds.overBudget,
                budgetUsed: ds.budgetUsed,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0);
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const metBadge = s.sound
                ? `<span class="stickysim-cm-badge stickysim-cm-yes">` + T(`cm_won`) + `</span>`
                : `<span class="stickysim-cm-badge stickysim-cm-no">` + T(`cm_notwon`) + `</span>`;
            let failBadges = ``;
            if (s.overclaimedFlag) failBadges += ` <span class="stickysim-cm-badge stickysim-cm-fail">` + T(`cm_overclaim`) + `</span>`;
            if (s.overBudget) failBadges += ` <span class="stickysim-cm-badge stickysim-cm-fail">` + T(`cm_overbudget`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="stickysim-cm-metric"><span class="stickysim-cm-mv">` + Math.round(s.behavior || 0) + `</span><span class="stickysim-cm-ml">` + T(`cm_m_behavior`) + `</span></div>`
                + `<div class="stickysim-cm-metric"><span class="stickysim-cm-mv">` + Math.round(s.transfer || 0) + `</span><span class="stickysim-cm-ml">` + T(`cm_m_transfer`) + `</span></div>`
                + `<div class="stickysim-cm-metric"><span class="stickysim-cm-mv">` + Math.round(s.credibility || 0) + `</span><span class="stickysim-cm-ml">` + T(`cm_m_cred`) + `</span></div>`
                + `<div class="stickysim-cm-metric"><span class="stickysim-cm-mv">` + Math.round(Number(s.budgetUsed || 0)) + `</span><span class="stickysim-cm-ml">` + T(`cm_m_budget`) + `</span></div>`;
            return ``
                + `<div class="stickysim-completion">`
                +   `<div class="stickysim-cm-head">`
                +     `<div class="stickysim-cm-score">` + score + `<span class="stickysim-cm-score-max">/100</span></div>`
                +     `<div class="stickysim-cm-grade">` + grade + ` ` + metBadge + failBadges + `</div>`
                +   `</div>`
                +   `<div class="stickysim-cm-metrics">` + metrics + `</div>`
                +   `<div class="stickysim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="stickysim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overclaimed) return window.mySimulation.t(`hint_overclaim`);
            if (ds.overBudget) return window.mySimulation.t(`hint_overbudget`);
            if (ds.transfer < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_transfer`);
            if (ds.credibility < 35) return window.mySimulation.t(`hint_credibility`);
            if (state.currentPeriod >= 3 && ds.behavior < 45) return window.mySimulation.t(`hint_behind`);
            if (ds.behavior >= this.TARGET_BEHAVIOR && ds.credibility >= 60 && ds.transfer >= 50) return window.mySimulation.t(`hint_strong`);
            return null;
        }

